  1	//! `std::cout << float`, which is glibc `printf("%g", (double) v)` at the
  2	//! default stream precision of 6.
  3	//!
  4	//! Every `f32` has a finite exact decimal expansion, so this expands the value
  5	//! exactly and then rounds that expansion to six significant digits. Working
  6	//! from the exact digits is what makes ties come out right: glibc rounds half
  7	//! to even, so `100000.5` prints as `100000` while `100001.5` prints as
  8	//! `100002`. Choosing `%e` or `%f` and trimming trailing zeros then follows
  9	//! the usual `%g` rules.
 10	
 11	use super::super::bignum::BigUint;
 12	
 13	/// Significant digits `%g` keeps at the default precision.
 14	const P: usize = 6;
 15	
 16	pub fn format_g6(v: f32) -> String {
 17	    if v.is_nan() {
 18	        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
 19	    }
 20	    let sign = if v.is_sign_negative() { "-" } else { "" };
 21	    if v.is_infinite() {
 22	        return format!("{}inf", sign);
 23	    }
 24	
 25	    let bits = v.to_bits();
 26	    let frac = bits & 0x7f_ffff;
 27	    let biased = ((bits >> 23) & 0xff) as i32;
 28	    if biased == 0 && frac == 0 {
 29	        return format!("{}0", sign);
 30	    }
 31	    // |v| = m * 2^e with m an integer.
 32	    let (m, e) = if biased == 0 {
 33	        (frac, -149i32)
 34	    } else {
 35	        (frac | (1 << 23), biased - 127 - 23)
 36	    };
 37	
 38	    // Exact decimal expansion: |v| = digits * 10^scale.
 39	    let mut n = BigUint::from_u64(u64::from(m));
 40	    let scale = if e >= 0 {
 41	        n.shl_bits(e as u64);
 42	        0i64
 43	    } else {
 44	        n.mul_pow5((-e) as u32);
 45	        i64::from(e)
 46	    };
 47	    let ds = n.to_decimal_string();
 48	    let db = ds.as_bytes();
 49	
 50	    // Decimal exponent of the leading digit, then round to P digits.
 51	    let mut x = db.len() as i64 - 1 + scale;
 52	    let mut sig: Vec<u8> = Vec::with_capacity(P);
 53	    if db.len() <= P {
 54	        sig.extend_from_slice(db);
 55	        sig.resize(P, b'0');
 56	    } else {
 57	        sig.extend_from_slice(&db[..P]);
 58	        let next = db[P];
 59	        let rest_nonzero = db[P + 1..].iter().any(|&d| d != b'0');
 60	        let tie_up = rest_nonzero || (sig[P - 1] - b'0') % 2 == 1;
 61	        if next > b'5' || (next == b'5' && tie_up) {
 62	            round_up(&mut sig, &mut x);
 63	        }
 64	    }
 65	
 66	    let body = if x < -4 || x >= P as i64 {
 67	        // %e with precision P-1, trailing zeros trimmed.
 68	        let mut mant = String::new();
 69	        mant.push(sig[0] as char);
 70	        let f = trim_zeros(&sig[1..]);
 71	        if !f.is_empty() {
 72	            mant.push('.');
 73	            mant.push_str(&f);
 74	        }
 75	        format!("{}e{}{:02}", mant, if x < 0 { '-' } else { '+' }, x.abs())
 76	    } else if x >= 0 {
 77	        // %f with the point inside the digits we have.
 78	        let cut = x as usize + 1;
 79	        let int = String::from_utf8_lossy(&sig[..cut]).into_owned();
 80	        let f = trim_zeros(&sig[cut..]);
 81	        if f.is_empty() {
 82	            int
 83	        } else {
 84	            format!("{}.{}", int, f)
 85	        }
 86	    } else {
 87	        // %f with leading zeros between the point and the digits.
 88	        let mut fdigits = vec![b'0'; (-x - 1) as usize];
 89	        fdigits.extend_from_slice(&sig);
 90	        format!("0.{}", trim_zeros(&fdigits))
 91	    };
 92	    format!("{}{}", sign, body)
 93	}
 94	
 95	/// Increment the digit string, carrying; an all-nines string becomes 1 followed
 96	/// by zeros and bumps the exponent.
 97	fn round_up(sig: &mut Vec<u8>, x: &mut i64) {
 98	    for i in (0..sig.len()).rev() {
 99	        if sig[i] == b'9' {
100	            sig[i] = b'0';
101	        } else {
102	            sig[i] += 1;
103	            return;
104	        }
105	    }
106	    sig.insert(0, b'1');
107	    sig.truncate(P);
108	    *x += 1;
109	}
110	
111	fn trim_zeros(d: &[u8]) -> String {
112	    let mut end = d.len();
113	    while end > 0 && d[end - 1] == b'0' {
114	        end -= 1;
115	    }
116	    String::from_utf8_lossy(&d[..end]).into_owned()
117	}

